INSERT INTO recipes(title,description,image,cuisine,dietary_preference,difficulty,prep_time,cook_time,servings,ingredients,instructions,cooking_tips,status,featured) VALUES
('Malawian Nsima with Beef','A comforting staple meal with tender beef and tomato relish.','https://images.unsplash.com/photo-1547592180-85f173990554?auto=format&fit=crop&w=900&q=80','African','General','Medium',20,45,4,'Maize flour\nBeef\nTomatoes\nOnion','Cook relish. Simmer beef until tender. Prepare nsima by gradually adding maize flour to boiling water and stirring until firm.','Add flour slowly.','approved',1),
('Thai Green Curry','Fragrant coconut curry with vegetables and herbs.','https://images.unsplash.com/photo-1455619452474-d2be8b1e70cd?auto=format&fit=crop&w=900&q=80','Asian','General','Medium',15,25,4,'Coconut milk\nCurry paste\nChicken or tofu\nBasil','Fry curry paste. Add coconut milk and protein. Simmer, add vegetables and basil.','Taste before adding salt.','approved',1),
('Creamy Italian Pasta','Quick pasta with garlic, cream and parmesan.','https://images.unsplash.com/photo-1473093295043-cdd812d0e601?auto=format&fit=crop&w=900&q=80','Italian','Vegetarian','Easy',10,20,3,'Pasta\nGarlic\nCream\nParmesan','Cook pasta. Sauté garlic, add cream and parmesan, then toss with pasta.','Reserve pasta water.','approved',1),
('Fresh Fruit Smoothie','A bright breakfast smoothie packed with fresh fruit.','https://images.unsplash.com/photo-1502741224143-90386d7f8c82?auto=format&fit=crop&w=900&q=80','American','Vegan','Easy',5,0,2,'Banana\nMango\nBerries\nPlant milk','Blend all ingredients until smooth. Serve cold.','Freeze fruit first.','approved',1),
('Homemade Pizza','Crisp-edged pizza with a simple tomato base.','https://images.unsplash.com/photo-1574071318508-1cdbab80d002?auto=format&fit=crop&w=900&q=80','European','Vegetarian','Medium',30,15,4,'Flour\nYeast\nTomato sauce\nMozzarella','Make dough and let it rise. Stretch, top and bake in a hot oven.','Preheat the oven well.','approved',1),
('African Peanut Stew','A rich stew with tomatoes and peanut butter.','https://images.unsplash.com/photo-1547592166-23ac45744acd?auto=format&fit=crop&w=900&q=80','African','Vegan','Easy',15,35,4,'Peanut butter\nTomatoes\nSweet potato\nSpinach','Sauté onion. Add tomatoes and sweet potato. Simmer, stir in peanut butter and finish with spinach.','Thin with stock if needed.','approved',1),
('Mexican Tacos','Bright tacos with beans, salsa and avocado.','https://images.unsplash.com/photo-1551504734-5ee1c4a1479b?auto=format&fit=crop&w=900&q=80','Mexican','Vegan','Easy',15,20,4,'Tortillas\nBeans\nAvocado\nTomato\nLime','Season beans. Warm tortillas. Fill and top with salsa and avocado.','Add lime before serving.','approved',1),
('Chocolate Cake','Moist chocolate cake for celebrations.','https://images.unsplash.com/photo-1578985545062-69928b1d9587?auto=format&fit=crop&w=900&q=80','European','Vegetarian','Medium',20,35,8,'Flour\nCocoa\nSugar\nEggs\nMilk','Mix wet and dry ingredients. Combine and bake until done.','Do not overmix.','approved',1),
('Vegetable Stir Fry','Fast colourful vegetables with a savoury sauce.','https://images.unsplash.com/photo-1512058564366-18510be2db19?auto=format&fit=crop&w=900&q=80','Asian','Vegan','Easy',15,10,3,'Broccoli\nCarrot\nPepper\nSoy sauce','Heat pan. Stir-fry vegetables quickly and add sauce at the end.','Keep vegetables crisp.','approved',1),
('Mediterranean Chickpea Bowl','Fresh chickpeas, herbs and lemon dressing.','https://images.unsplash.com/photo-1512621776951-a57141f2eefd?auto=format&fit=crop&w=900&q=80','Mediterranean','Vegan','Easy',15,10,2,'Chickpeas\nCucumber\nTomato\nParsley\nLemon','Combine ingredients and dress with lemon and herbs.','Chill before serving.','approved',1);
